func newNode(rn *RawNode) node {
	return node{
		propc:      make(chan msgWithResult),
		recvc:      make(chan *pb.Message),
		confc:      make(chan *pb.ConfChangeV2),
		confstatec: make(chan *pb.ConfState),
		readyc:     make(chan Ready),
		advancec:   make(chan struct{}),
